import{_ as e,o,c as a,a3 as r}from"./chunks/framework.DAK02U1-.js";const g=JSON.parse('{"title":"Compatibility","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Compatibility | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/xclang/reference/compatibility"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/xclang/reference/compatibility"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/xclang/reference/compatibility"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/xclang/reference/compatibility"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/xclang/reference/compatibility"}]]},"headers":[],"relativePath":"xclang/reference/compatibility.md","filePath":"en/xclang/reference/compatibility.md","lastUpdated":1791227177000}'),i={name:"xclang/reference/compatibility.md"};function n(d,t,l,c,s,h){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="compatibility" tabindex="-1">Compatibility <a class="header-anchor" href="#compatibility" aria-label="Permalink to &quot;Compatibility&quot;">​</a></h1><p>The oldest systems and tools xclang and the programs it builds work with, and what is not supported.</p><h2 id="the-toolchain" tabindex="-1">The toolchain <a class="header-anchor" href="#the-toolchain" aria-label="Permalink to &quot;The toolchain&quot;">​</a></h2><table tabindex="0"><thead><tr><th>host</th><th>needs</th></tr></thead><tbody><tr><td>Linux x64, arm64</td><td>glibc 2.17 or later; nothing else (clang and lld link libc++ statically)</td></tr><tr><td>macOS arm64, x64</td><td>macOS 13 or later; for macOS targets, Xcode or the Command Line Tools (the SDK)</td></tr><tr><td>Windows x64, arm64</td><td>Windows 10 or later (UCRT is part of the OS)</td></tr></tbody></table><h2 id="programs-it-builds" tabindex="-1">Programs it builds <a class="header-anchor" href="#programs-it-builds" aria-label="Permalink to &quot;Programs it builds&quot;">​</a></h2><table tabindex="0"><thead><tr><th>target</th><th>runs on</th></tr></thead><tbody><tr><td>Linux x64, arm64</td><td>glibc 2.17 or later: CentOS 7, Debian 8, Ubuntu 14.04 and every later distribution with glibc</td></tr><tr><td>Windows x64, arm64</td><td>Windows 10 or later, where UCRT is part of the OS</td></tr><tr><td>macOS arm64, x64</td><td>macOS 13.0 or later (<code>-mmacos-version-min=13.0</code> in the config file; one given on the command line comes after it and replaces it)</td></tr></tbody></table><p>What a program loads at run time is in <a href="./../design/hermeticity">hermeticity</a>.</p><h2 id="build-tools" tabindex="-1">Build tools <a class="header-anchor" href="#build-tools" aria-label="Permalink to &quot;Build tools&quot;">​</a></h2><table tabindex="0"><thead><tr><th>tool</th><th>version</th><th>why</th></tr></thead><tbody><tr><td>CMake</td><td>3.28 or later</td><td>the first that builds C++20 modules without experimental switches; <code>find_package(xclang)</code> refuses older ones</td></tr><tr><td>Ninja</td><td>1.11 or later</td><td>what CMake requires to build C++20 modules; Ninja and Ninja Multi-Config are the generators that build them for these targets</td></tr><tr><td>Bazel</td><td>9</td><td>the module&#39;s toolchains are rules_cc 0.2.25&#39;s; C++20 modules need <code>--experimental_cpp_modules</code></td></tr><tr><td>Xcode</td><td>one whose SDK ld64.lld reads: Xcode 27&#39;s macOS 27 SDK needs 23.1.2.6 or later (patch 0009)</td><td></td></tr><tr><td>Rust</td><td>Rust&#39;s <code>*-windows-gnullvm</code> targets for Windows (not <code>*-windows-gnu</code>)</td><td>see <a href="./../integrations/cargo">Rust and cargo</a></td></tr></tbody></table><h2 id="not-supported" tabindex="-1">Not supported <a class="header-anchor" href="#not-supported" aria-label="Permalink to &quot;Not supported&quot;">​</a></h2><ul><li><strong>Linux, from glibc 2.17</strong>: no <code>-static-pie</code> (glibc 2.17 has no <code>rcrt1.o</code>); <code>-pg</code> needs <code>-no-pie</code> (its <code>gcrt1.o</code> is not position-independent); no <code>quadmath.h</code> (<code>libquadmath</code> is GCC&#39;s own; <code>__float128</code> arithmetic works).</li><li><strong>No OpenMP runtime</strong> (<code>-fopenmp</code>), <strong>no MemorySanitizer</strong> (it needs every library instrumented, libc++ too: <a href="./../design/roadmap#libc-built-on-demand">roadmap</a>), <strong>no sanitizers for Windows targets</strong>.</li><li><strong>No clang-format, clang-tidy or clangd binaries</strong>: xclang is a compiler toolchain; libclang has the libraries tools on clang link.</li><li><strong>One libc++ per shared object</strong>: a standard exception thrown by one shared library is caught by type in another only on Windows; on Linux and macOS only as <code>catch (...)</code>. See <a href="./../design/hermeticity#one-libc-per-shared-object">hermeticity</a>.</li><li><strong>macOS targets from Linux or Windows hosts</strong>: not yet (<a href="./../design/roadmap">roadmap</a>); the SDK is Xcode&#39;s.</li><li><strong>MSVC-ABI targets</strong> (<code>*-pc-windows-msvc</code>): not yet, in research. clang, clang-cl and lld-link build for them against the user&#39;s own MSVC and Windows SDK, as upstream clang does, but xclang has no config files or runtimes for them yet.</li><li><strong>Building conda-forge packages</strong>: conda-forge&#39;s compilers link dynamically against packaged runtimes and integrate with <code>run_exports</code>; xclang does neither.</li></ul>',11)])])}const p=e(i,[["render",n]]);export{g as __pageData,p as default};
